/* @lc app=leetcode id=2709 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun pf(x: Int): List<Int> = (2..Math.sqrt(x.toDouble()).toInt()).fold(x to listOf<Int>()) { (r, ps), d -> if (r % d != 0) r to ps else generateSequence(r) { if (it % d == 0) it / d else null }.last().let { it to ps + d } }.let { (r, ps) -> if (r > 1) ps + r else ps } fun canTraverseAllPairs(nums: IntArray): Boolean = nums.size.let { n -> if (n == 1) true else if (nums.any { it == 1 }) false else IntArray(n + 100001) { it }.let { p -> nums.forEachIndexed { i, x -> pf(x).forEach { q -> p[find(p, i)] = find(p, n + q) } }.let { (0 until n).map { find(p, it) }.distinct().size == 1 } } } }